-- Round 4: a messy set of accounts left behind by "the previous admin".
-- DO NOT EDIT THIS FILE. The grader always uses the instructor's copy.
-- bootstrap.sh runs it as root, after schema.sql and load.sql, and then runs your fixes.sql.
-- It starts by dropping these accounts, so it is safe to run again and again.

DROP USER IF EXISTS
  's6705140050_webapp'@'%', 's6705140050_webapp'@'localhost',
  's6705140050_kiosk'@'localhost', 's6705140050_kiosk'@'%',
  's6705140050_intern'@'%', 's6705140050_intern'@'localhost',
  's6705140050_etl'@'localhost', 's6705140050_etl'@'%',
  's6705140050_report'@'localhost', 's6705140050_report'@'%';

CREATE USER 's6705140050_webapp'@'%' IDENTIFIED BY 'Webapp#2026';
GRANT ALL PRIVILEGES ON *.* TO 's6705140050_webapp'@'%' WITH GRANT OPTION;

CREATE USER 's6705140050_kiosk'@'localhost' IDENTIFIED BY '';
GRANT SELECT ON reg_6705140050.students TO 's6705140050_kiosk'@'localhost';

CREATE USER 's6705140050_intern'@'%' IDENTIFIED BY 'Intern#2025';
GRANT SELECT, INSERT, UPDATE ON reg_6705140050.* TO 's6705140050_intern'@'%';

CREATE USER 's6705140050_etl'@'localhost' IDENTIFIED BY 'Etl#2026';
GRANT FILE ON *.* TO 's6705140050_etl'@'localhost';
GRANT INSERT ON reg_6705140050.enrollments TO 's6705140050_etl'@'localhost';

CREATE USER 's6705140050_report'@'localhost' IDENTIFIED BY 'Report#2026';
GRANT SELECT, INSERT, UPDATE, DELETE ON reg_6705140050.* TO 's6705140050_report'@'localhost';
